import {buildWards} from './city.js';
export async function initDirectory(api){
 const [wards,facilities,resorts]=await Promise.all(['ward-details','facilities','resorts'].map(n=>fetch(`data/${n}.json`).then(r=>r.json())));
 const panel=document.createElement('aside');panel.id='directoryPanel';panel.className='panel';panel.style.cssText='display:none;right:18px;top:76px;width:min(390px,94vw);max-height:74vh;overflow:auto;padding:18px;z-index:10';
 panel.innerHTML='<button id="dirClose" style="float:right">Close ✕</button><h2>Explore Kollam</h2><p>Wards, healthcare & stays</p><select id="dirKind"><option value="hospital">Hospitals</option><option value="clinic">Clinics</option><option value="dispensary">Dispensaries</option><option value="ward">Ward boundaries</option><option value="resort">Resorts</option></select><select id="dirBody"></select><input id="dirSearch" placeholder="Search name or ward number"><button id="dirNearest">Nearest clinic to map centre</button><p id="dirNote"></p><div id="dirResults"></div>';
 document.body.append(panel);const button=document.createElement('button');button.textContent='Wards & healthcare';document.querySelector('#tools').append(button);button.onclick=()=>{api.onOpen?.();panel.style.display='block';render()};panel.querySelector('#dirClose').onclick=()=>panel.style.display='none';
 const $=s=>panel.querySelector(s),kind=$('#dirKind'),body=$('#dirBody'),search=$('#dirSearch'),list=$('#dirResults');
 for(const lb of [...new Set(wards.map(w=>w.lb))].sort()){const o=new Option(lb,lb);body.add(o)}body.value='Kollam';let layer=null,anchor=null;
 const distance=(a,b)=>{const r=Math.PI/180,dlat=(a[1]-b[1])*r,dlon=(a[0]-b[0])*r;return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a[1]*r)*Math.cos(b[1]*r)*Math.sin(dlon/2)**2))};
 function render(){
  body.style.display=kind.value==='ward'?'block':'none';if(layer){api.scene.remove(layer);layer.geometry?.dispose();layer=null}
  let rows=kind.value==='ward'?wards.filter(w=>w.lb===body.value):kind.value==='resort'?resorts:facilities.filter(f=>f.kind===kind.value);
  if(kind.value==='ward'){layer=buildWards(rows,api.T);layer.visible=true;api.scene.add(layer)}
  const q=search.value.toLowerCase();rows=rows.filter(r=>(`${r.name} ${r.no||''} ${r.address||''}`).toLowerCase().includes(q));if(anchor&&kind.value==='clinic')rows.sort((a,b)=>distance(a.ll,anchor)-distance(b.ll,anchor));
  $('#dirNote').textContent=kind.value==='ward'?`${rows.length} wards · 2024 delimitation source; may differ from notified boundaries.`:`${rows.length} mapped listings. Call to confirm services. Distances are straight-line, not travel times.`;
  list.replaceChildren();for(const r of rows.slice(0,100)){const card=document.createElement('div');card.style.cssText='padding:12px 0;border-bottom:1px solid #ffffff22';const title=document.createElement('button');title.textContent=r.no?`${r.no} · ${r.name}`:r.name;title.style.cssText='color:#e9b872;text-align:left;font-size:15px';title.onclick=()=>api.flyTo({ll:r.ll,d:r.no?2200:1000,h:62,t:68});card.append(title);const details=document.createElement('p');details.textContent=r.address||r.lb||'';card.append(details);if(anchor&&r.kind==='clinic'){const p=document.createElement('p');p.textContent=`${distance(r.ll,anchor).toFixed(2)} km from selected map centre`;card.append(p)}if(r.phone){const a=document.createElement('a');a.href='tel:'+r.phone;a.textContent=r.phone;card.append(a)}const source=document.createElement('a');source.href=r.source||'https://github.com/madpk/kerala-ward-map';source.target='_blank';source.rel='noopener';source.textContent=' · Source';card.append(source);list.append(card)}
 }
 kind.onchange=()=>{anchor=null;render()};body.onchange=render;search.oninput=render;$('#dirNearest').onclick=()=>{kind.value='clinic';search.value='';anchor=api.T.toLL(api.controls.target.x,api.controls.target.z);render()};
}
